/* ts-proto-descriptors 2.1.0 (npm, ISC; generated by ts-proto with usePrototypeForDefaults): the
 * CodeGeneratorRequest as ts-proto 2.x sees it. Decoded messages are `Object.create(createBase…())`:
 * fields read from the wire are own properties, the others come from the prototype with
 * proto3-style defaults ("" / 0 / false / [] / undefined for messages). So `field.oneofIndex` is 0
 * when absent but `hasOwnProperty("oneofIndex")` is false, `field.options` is undefined (NULL)
 * when absent, and `field.options.packed` is false unless set.
 *
 * The wire bytes are parsed with pkg/pb (protobuf-es semantics): unlike ts-proto-descriptors, a
 * repeated singular message field is merged, and an unknown value of a closed enum (label, type,
 * jstype, ...) is not seen. Such requests are not produced by protoc or buf. */
#ifndef TPD_H
#define TPD_H

#include "pb.h"
#include "util.h"

/* FieldOptions_JSType */
enum { TPD_JS_NORMAL = 0, TPD_JS_STRING = 1, TPD_JS_NUMBER = 2 };
/* Edition */
enum { TPD_EDITION_UNKNOWN = 0, TPD_EDITION_PROTO2 = 998, TPD_EDITION_PROTO3 = 999, TPD_EDITION_2023 = 1000,
       TPD_EDITION_2024 = 1001 };

typedef struct {
	bool packed, deprecated;
	int32_t jstype;
} TpdFieldOptions;

typedef struct {
	bool deprecated, map_entry;
} TpdMessageOptions;

typedef struct {
	bool deprecated;
} TpdOptions; /* FileOptions, EnumOptions, EnumValueOptions, ServiceOptions */

/* `_unknownFields` of a decoded message: tag -> the raw values (after the tag) in wire order; keys
 * in Object.entries order (ascending tags) */
typedef struct {
	uint32_t tag;
	int nvalue;
	Str *value;
} TpdUnknownField;

typedef struct {
	bool deprecated;
	int32_t idempotency_level;
	TpdUnknownField *unknown; /* NULL: `_unknownFields` undefined */
	int nunknown;
} TpdMethodOptions;

typedef struct {
	const char *name;
	int32_t number;
	int32_t label; /* default 1 */
	int32_t type;  /* default 1 */
	const char *type_name, *extendee, *default_value, *json_name;
	int32_t oneof_index;
	bool has_oneof_index; /* hasOwnProperty("oneofIndex") */
	bool has_label, has_type, has_type_name, has_json_name; /* own properties (for `{ ...field }`) */
	bool proto3_optional;
	TpdFieldOptions *options; /* NULL: undefined */
} TpdField;

typedef struct {
	const char *name;
	int32_t number;
	TpdOptions *options;
} TpdEnumValue;

typedef struct {
	const char *name;
	TpdEnumValue **value;
	int nvalue;
	TpdOptions *options;
} TpdEnum;

typedef struct {
	const char *name;
} TpdOneof;

typedef struct TpdMessage TpdMessage;
struct TpdMessage {
	const char *name;
	TpdField **field;
	int nfield;
	TpdMessage **nested_type;
	int nnested_type;
	TpdEnum **enum_type;
	int nenum_type;
	int nextension_range;
	TpdField **extension;
	int nextension;
	TpdOneof **oneof_decl;
	int noneof_decl;
	TpdMessageOptions *options;
};

typedef struct {
	const char *name, *input_type, *output_type;
	TpdMethodOptions *options;
	bool client_streaming, server_streaming;
} TpdMethod;

typedef struct {
	const char *name;
	TpdMethod **method;
	int nmethod;
	TpdOptions *options;
} TpdService;

typedef struct {
	const int32_t *path;
	int npath;
	Str leading_comments, trailing_comments;
	Str *leading_detached_comments;
	int nleading_detached_comments;
} TpdLocation;

typedef struct {
	const char *name, *package, *syntax;
	const char **dependency;
	int ndependency;
	TpdMessage **message_type;
	int nmessage_type;
	TpdEnum **enum_type;
	int nenum_type;
	TpdService **service;
	int nservice;
	TpdField **extension;
	int nextension;
	TpdOptions *options;
	bool has_source_code_info;
	TpdLocation **location;
	int nlocation;
	int32_t edition;
	PbMsg *raw; /* the parsed message (for encoding it again) */
} TpdFile;

typedef struct {
	const char **file_to_generate;
	int nfile_to_generate;
	Str parameter;
	TpdFile **proto_file;
	int nproto_file;
	bool has_compiler_version;
	int32_t major, minor, patch;
} TpdRequest;

/* Reads the request (pb_decode'd CodeGeneratorRequest). */
TpdRequest *tpd_request(const PbMsg *req);

#endif
